<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('audit.view');$q=trim((string)input('q'));$module=trim((string)input('module'));$page=page_int();[$limit,$offset]=pagination($page);$where=[];$params=[];if($q!==''){$where[]='(l.action LIKE ? OR l.record_id LIKE ? OR a.name LIKE ?)';$params=array_fill(0,3,'%'.$q.'%');}if($module!==''){$where[]='l.module=?';$params[]=$module;}$sqlWhere=$where?' WHERE '.implode(' AND ',$where):'';$count=db()->prepare('SELECT COUNT(*) FROM audit_logs l LEFT JOIN admins a ON a.id=l.admin_id'.$sqlWhere);$count->execute($params);$total=(int)$count->fetchColumn();$stmt=db()->prepare('SELECT l.*,a.name admin_name FROM audit_logs l LEFT JOIN admins a ON a.id=l.admin_id'.$sqlWhere.' ORDER BY l.id DESC LIMIT '.$limit.' OFFSET '.$offset);$stmt->execute($params);$rows=$stmt->fetchAll();$modules=db()->query('SELECT DISTINCT module FROM audit_logs ORDER BY module')->fetchAll(PDO::FETCH_COLUMN);$pageTitle='Audit log';$pageSubtitle='Database-immutable record of sensitive administrator actions';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Action, record or admin"><select name="module"><option value="">All modules</option><?php foreach($modules as $m):?><option <?=$module===$m?'selected':''?>><?=e($m)?></option><?php endforeach?></select><button class="btn">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Date</th><th>Admin</th><th>Action</th><th>Module</th><th>Record</th><th>IP</th><th>Change</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['admin_name']??'System')?></td><td><strong><?=e($r['action'])?></strong></td><td><?=e($r['module'])?></td><td><?=e($r['record_id']??'—')?></td><td><?=e($r['ip_address']??'—')?></td><td><details><summary>View</summary><small>Before: <?=e($r['old_data']??'—')?><br>After: <?=e($r['new_data']??'—')?></small></details></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No audit entries match these filters.</div><?php endif?></div><div class="pagination"><?php for($i=1;$i<=ceil($total/$limit);$i++):?><a href="?<?=e(http_build_query(['q'=>$q,'module'=>$module,'page'=>$i]))?>"><?=$i?></a><?php endfor?></div></section><?php require APP_ROOT.'/includes/footer.php';

